using UnityEngine;using UnityEditor;using System;using System.Reflection;using System.Linq;using System.IO;using System.Collections.Generic;
public static class ValidateRack {public static string Main(){GameObject copy=null,fixture=null;var items=new List<GameObject>();int checks=0;void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}void Set(object t,string n,object v)=>t.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(t,v);
try{copy=UnityEngine.Object.Instantiate(UnityEngine.Object.FindObjectsByType<BicycleController>(FindObjectsSortMode.None).First(b=>!b.motorDriven).gameObject,new Vector3(10000,.73f,10000),Quaternion.identity);var bike=copy.GetComponent<BicycleController>();fixture=new GameObject("Rack test handler");fixture.SetActive(false);var camera=new GameObject("Camera").AddComponent<Camera>();camera.enabled=false;camera.transform.SetParent(fixture.transform,false);var player=fixture.AddComponent<PlayerController>();player.characterCamera=camera;player.enabled=false;var rider=fixture.AddComponent<PlayerBicycleInteraction>();rider.player=player;rider.bicycle=bike;var bags=fixture.AddComponent<BagInteraction>();bags.enabled=false;var carry=new GameObject("Carry").transform;carry.SetParent(fixture.transform,false);var tool=new GameObject("Tool");tool.transform.SetParent(fixture.transform);tool.SetActive(false);Set(bags,"shovel",tool.AddComponent<ShovelTool>());Set(bags,"carryAnchor",carry);Set(bags,"viewCamera",camera);fixture.transform.position=new Vector3(9998,0,10000);fixture.SetActive(true);
var sack=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/GrainPrototype/Grains/Sorting Sack.prefab"));items.Add(sack);var bag=sack.GetComponent<GrainContainer>();Set(bag,"kilograms",bag.CapacityKg);typeof(GrainContainer).GetMethod("ApplyFill",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(bag,null);sack.GetComponent<SackController>().Close=1;var take=typeof(BagInteraction).GetMethod("Take",BindingFlags.Instance|BindingFlags.NonPublic);Check((bool)take.Invoke(bags,new object[]{bag}),"Take bag");Check(rider.TryLoadBag(),"One bag fits");Check(bike.FreeBagCargoSlot()==null&&bike.FreeCargoSlot()==null,"Bag occupies entire rack");Check(Mathf.Abs(bike.transform.InverseTransformPoint(bag.WorldBounds.center).x)<.01f,"Bag centered on rack");Check(bike.HasCargo(bag.transform),"Bag recognized");Check((bool)take.Invoke(bags,new object[]{bag}),"Retrieve bag");Check(bike.FreeBagCargoSlot()!=null&&bike.FreeCargoSlot()!=null,"Rack frees after bag retrieval");
for(int i=0;i<2;i++){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);items.Add(g);g.transform.localScale=new Vector3(.32f,.4f,.36f);var box=g.AddComponent<BicycleCargoBox>();Check(box.Load(bike.FreeCargoSlot()),"Box "+i+" fits");Check(Mathf.Abs(bike.transform.InverseTransformPoint(g.transform.position).x)<.01f,"Box centered on rack");Check(!rider.TryLoadBag(),"Cannot mix bag with boxes");}
Check(bike.FreeCargoSlot()==null,"Third box blocked");var first=items[1].GetComponent<BicycleCargoBox>();Check(first.Unload(new Vector3(10002,1,10000)),"Unload first box");Check(!rider.TryLoadBag(),"Remaining box still blocks bag");Check(items[2].GetComponent<BicycleCargoBox>().Unload(new Vector3(10003,1,10000)),"Unload second box");Check(rider.TryLoadBag(),"Bag can reload after both boxes removed");string result="PASS "+checks+" bicycle rack capacity/ownership/placement checks";File.WriteAllText("output/Lawnmower/rack-validation.txt",result);return result;
}finally{foreach(var g in items)if(g)UnityEngine.Object.DestroyImmediate(g);if(fixture)UnityEngine.Object.DestroyImmediate(fixture);if(copy)UnityEngine.Object.DestroyImmediate(copy);}}}
